import{_ as a,o as i,c as t,a4 as e}from"./chunks/framework.BYKJayo6.js";const p=JSON.parse('{"title":"Anno 117 アップデート・パッチ情報｜3.0・2.1・2.0の変更点","description":"Anno 117（アノ117）の無料アップデート3.0・2.1・2.0の変更点を日本語でまとめています。新機能・バランス調整・PS5とPC版の主な修正を、公式パッチノートから抜き出しました。","frontmatter":{"title":"Anno 117 アップデート・パッチ情報｜3.0・2.1・2.0の変更点","description":"Anno 117（アノ117）の無料アップデート3.0・2.1・2.0の変更点を日本語でまとめています。新機能・バランス調整・PS5とPC版の主な修正を、公式パッチノートから抜き出しました。"},"headers":[],"relativePath":"guide/patch-notes.md","filePath":"guide/patch-notes.md"}'),r={name:"guide/patch-notes.md"};function o(n,l,h,d,s,u){return i(),t("div",null,[...l[0]||(l[0]=[e('<h1 id="アップデート・パッチ情報" tabindex="-1">アップデート・パッチ情報 <a class="header-anchor" href="#アップデート・パッチ情報" aria-label="Permalink to &quot;アップデート・パッチ情報&quot;">​</a></h1><p>無料アップデートの変更点を、新しい順にまとめています。公式パッチノート（英語）から、遊びに関わるものと、PS5・PC版の主な修正を抜き出しました。細かい不具合の修正は省いています。全文は各版の公式ページで読めます。</p><table tabindex="0"><thead><tr><th>版</th><th>配信日</th><th>同じ日に出たDLC</th></tr></thead><tbody><tr><td><a href="#update-3-0">3.0</a></td><td>2026年11月5日</td><td><a href="/guide/dlc03-dawn-of-delta.html">DLC03・デルタの夜明け</a></td></tr><tr><td><a href="#update-2-1">2.1</a></td><td>2026年9月17日</td><td>なし</td></tr><tr><td><a href="#update-2-0">2.0</a></td><td>2026年8月20日</td><td><a href="/guide/dlc02-hippodrome.html">DLC02・競馬場</a></td></tr></tbody></table><h2 id="update-3-0" tabindex="-1">3.0（2026年11月5日） <a class="header-anchor" href="#update-3-0" aria-label="Permalink to &quot;3.0（2026年11月5日） {#update-3-0}&quot;">​</a></h2><p>DLCを持っていなくても入る無料アップデートです。</p><h3 id="新機能" tabindex="-1">新機能 <a class="header-anchor" href="#新機能" aria-label="Permalink to &quot;新機能&quot;">​</a></h3><ul><li><strong>スタンプ機能</strong>：住居や生産施設の配置を保存して、あとで再利用できます。名前を付けたり、フォルダに分けたりもできます。PC版では、スタンプのファイルをほかの人と共有できます</li><li>統計メニューに「保管」タブと「アイテム・スペシャリスト」タブを追加 <ul><li>保管タブでは、保管中の商品、パッシブ貿易、アクティブ貿易、保管量の増減を確認できます</li><li>アイテム・スペシャリストタブでは、持っているスペシャリストと、まだ手に入れていないスペシャリスト、その入手元を一覧できます</li></ul></li><li>クエストログからクエストを隠せるようになりました。隠したクエストは、クエストブックから戻せます</li><li>前からのセーブを続ける人向けに、スタンプとメモ機能の短い紹介が出ます</li><li>栄誉の殿堂に新カテゴリ「アイギュプト」が加わりました。DLC03を持っていなくても使えます</li></ul><h3 id="遊びやすさ" tabindex="-1">遊びやすさ <a class="header-anchor" href="#遊びやすさ" aria-label="Permalink to &quot;遊びやすさ&quot;">​</a></h3><ul><li>祭りを自動で承認するオプションを追加（ゲームオプション）</li><li>祭りの総督の決定で、費用の商品を今どれだけ持っているかが表示されます</li><li>アップグレードの道具で、費用と一緒に建物の名前が出ます</li><li>交易ルートを消す前に確認が出ます</li><li>交易ルートの詳細画面で戻る操作をすると、画面ごと閉じずにルートの一覧に戻ります</li><li>アイテムの持ち物を開くと、場面に合った絞り込みが最初から選ばれています</li><li>カーソルの下にある建物と同じものを建てるショートカットを追加（キーは自分で割り当てます）</li><li>フォトモードで、カメラを建物の中に入れられます</li></ul><h3 id="バランス調整" tabindex="-1">バランス調整 <a class="header-anchor" href="#バランス調整" aria-label="Permalink to &quot;バランス調整&quot;">​</a></h3><ul><li><strong>難易度</strong>：新しいセーブでは「ノーマル」が既定になり、商品の消費量が増えます。「簡単」も選べます。消費がさらに75%増える最上位の難易度も追加されました。開始資金も増えます。前からのセーブには影響しません</li><li><strong>祭り</strong>：始めるのに必要な商品が、商品の価値で決まるようになりました。安い商品は多く、高い商品は少なく必要です。終盤の祭りの費用は、50,000コインから25,000コインに下がります</li><li><strong>水道橋のスペシャリスト</strong>：給水の効果が下がりました <ul><li>水の管理人-アクイラ・ドゥルシス：+200% → +100%</li><li>ドゥクトゥアリウス：+50% → +25%</li></ul></li><li><strong>祭壇</strong>：範囲がすべて22マスに揃いました</li><li><strong>貯水池</strong>：範囲が少し広がり、建てる前の表示と合うようになりました</li><li><strong>サンダラック苗木場</strong>：農園の扱いになり、農園向けの強化が効くようになりました</li><li><strong>リベルトゥスのパン</strong>：輝きで増えるパンの消費量が、プレブスと同じ水準まで下がりました</li><li><strong>都市ステータス</strong>：属性ペナルティの増え方が、人口ティア2・3の前後でゆるやかになりました。終盤の値は変わりません（<a href="/wiki/city-status.html">街の状況の段階</a>）</li><li><strong>護衛の依頼</strong>：護衛する船が速くなり、襲ってくる船は遠くに出るようになりました。護衛する船は、依頼を受けた灯台の近くに現れます</li></ul><p>公式パッチノートには「ラティウムの粉ひき所の生産時間 30秒→20秒」なども載っていますが、ゲームのデータでは2.0の時点で変わっています（<a href="#update-2-0">2.0</a>の欄に載せています）。</p><h3 id="主な修正-ps5・家庭用ゲーム機" tabindex="-1">主な修正（PS5・家庭用ゲーム機） <a class="header-anchor" href="#主な修正-ps5・家庭用ゲーム機" aria-label="Permalink to &quot;主な修正（PS5・家庭用ゲーム機）&quot;">​</a></h3><ul><li>家庭用ゲーム機で、自動セーブの上限が効いていなかったのを修正。手でセーブを消す必要がなくなります</li><li>PS5のマルチプレイで、進行中のセッションに加わるとセーブのプロファイルが二重にできることがあったのを修正</li><li>PS5で、総督のヴィラでスペシャリストを割り当てるときに、画面のキーボードが勝手に開くことがあったのを修正</li><li>コントローラーで、マップの端にいる船を選び直せるようになりました</li><li>インストールサイズが小さくなりました。そのぶん、この更新のダウンロードは大きくなります</li></ul><h3 id="主な修正-pc" tabindex="-1">主な修正（PC） <a class="header-anchor" href="#主な修正-pc" aria-label="Permalink to &quot;主な修正（PC）&quot;">​</a></h3><ul><li>画質の自動設定で、「低」のときにフレーム生成が有効になってしまうのを修正</li><li>RTX 30シリーズでは、自動設定でFSR 3のフレーム生成が既定になります</li><li>推奨スペックのPCで、大きく発展した都市の動作が軽くなりました</li><li>ウィンドウモードの大きさが、次に起動したときも保たれます</li><li>MODが合わないときの説明に、違っているMODの名前が出ます。ポーズメニューで、MODを使っているゲームかどうかが分かります</li></ul><h3 id="主な修正-全機種" tabindex="-1">主な修正（全機種） <a class="header-anchor" href="#主な修正-全機種" aria-label="Permalink to &quot;主な修正（全機種）&quot;">​</a></h3><ul><li>「期限切れのメモ」の通知を押すと落ちる不具合、特定のセーブを読み込んだ直後に落ちる不具合を修正</li><li>交易ルートの船が、同じ島に戻り続けることがあったのを修正</li><li>ブドウ・ハチの巣・ワインが、交易と統計の画面に出ていなかったのを修正</li><li>騎兵が攻撃の相手を行ったり来たり変えていたのを修正</li><li>スペシャリストを外す順番で、名声が大きく増減していたのを修正</li><li>皇帝の商人（英語名 Emperor&#39;s traders）との評判が低くても、失った旗艦の代わりを買えるようになりました</li><li>マルチプレイの同期ずれ（新しい協力キャンペーン、プレイヤーが置いたメモ、MODの違いが原因のもの）を修正</li></ul><p>公式パッチノート：<a href="https://www.anno-union.com/updates/anno-117-pax-romana-patch-3-0/" target="_blank" rel="noreferrer">Anno 117: Pax Romana - Patch 3.0（Anno Union）</a></p><h2 id="update-2-1" tabindex="-1">2.1（2026年9月17日） <a class="header-anchor" href="#update-2-1" aria-label="Permalink to &quot;2.1（2026年9月17日） {#update-2-1}&quot;">​</a></h2><h3 id="バランス調整-1" tabindex="-1">バランス調整 <a class="header-anchor" href="#バランス調整-1" aria-label="Permalink to &quot;バランス調整&quot;">​</a></h3><p>ヒロイックのスペシャリストのうち、強すぎた3人が調整されました。</p><ul><li><strong>ラエウィヌス、ウルカヌスのつるはし</strong>：効果の対象が、採石場・金選鉱・粘土穴だけになりました（砂精製所を使った稼ぎができなくなります）</li><li><strong>キルョカンシ、洞穴のごとき飾り箱を持つ男</strong>：ライバルとのパッシブ貿易だけが対象になりました。プレイヤー同士の交易は数えません</li><li><strong>ティランナ、生粋の多色主義者</strong>：染料ではなく顔料に効くようになりました</li></ul><p>ほかの変更です。</p><ul><li>交易の強化は、NPCとプレイヤーの間の数量限定の取引にだけ効くようになりました</li><li>サンダラック苗木場が農園の分類になりました</li><li>期間限定チャレンジの警告が読みやすくなりました</li><li>外観変更用のDLC「Echoes of Kassandra Pack」に対応しました</li></ul><h3 id="主な修正" tabindex="-1">主な修正 <a class="header-anchor" href="#主な修正" aria-label="Permalink to &quot;主な修正&quot;">​</a></h3><ul><li><strong>PS5</strong>：前からのセーブを読み込むと落ちることがあったのを修正</li><li>競馬場（DLC02）の不具合をいくつか修正。レース中に行進の部隊が出る、計画の研究が解放されない、などです</li><li>カエシリアを助けたときの外交の悪化が、いつまでも消えなかったのを修正</li><li>分かれた水道橋をつないだときの誤った通知、「持ち物がいっぱい」の誤った警告を修正</li><li>マルチプレイで、もう一度招待すると読み込み画面が終わらないことがあったのを修正</li></ul><p>公式パッチノート：<a href="https://www.anno-union.com/updates/anno-117-pax-romana-patch-2-1/" target="_blank" rel="noreferrer">Anno 117: Pax Romana - Patch 2.1（Anno Union）</a></p><h2 id="update-2-0" tabindex="-1">2.0（2026年8月20日） <a class="header-anchor" href="#update-2-0" aria-label="Permalink to &quot;2.0（2026年8月20日） {#update-2-0}&quot;">​</a></h2><p>DLC02と同じ日に配信された、DLC不要の大型アップデートです。</p><h3 id="新機能-1" tabindex="-1">新機能 <a class="header-anchor" href="#新機能-1" aria-label="Permalink to &quot;新機能&quot;">​</a></h3><ul><li><strong>賓客</strong>：名声と輝きに応じて各地から賓客が訪れ、新しいスペシャリストなどをもたらします。確率は<a href="/guide/dlc02-hippodrome.html#来訪する専門家の確率">DLC02ガイドの「来訪する専門家の確率」</a>にまとめています</li><li><strong>ヒロイックのスペシャリスト</strong>：新しいレア度。とても珍しく、名声のコストが高いぶん効果が強力です。同じ人は重ねて現れず、全員集めると出なくなります。効果は、名声が十分な都市でしか働きません <ul><li>（例）「パルディウス」— チーズによる人口+2・健康+1、羊牧場のチーズ産出+1t/12サイクル、羊牧場の必要労働力が75%増える（この効果は未確認です）</li></ul></li><li>住民から、くり返し受けられるクエストが出るようになりました</li><li><strong>フォトモード</strong>：自由に動くカメラ、時間帯の選択、レンズ効果</li><li><strong>メモ機能</strong>：ワールドにメモを置けます。時間がきたら知らせるタイマーも付けられます</li><li><strong>置き換え</strong>：選んだ建物の下にあるものをまとめて取り壊して建てられます</li><li>栄誉の殿堂のページを追加</li><li>期間限定チャレンジが、全機種でUbisoft Connectから遊べるようになりました</li><li>割り当てのないショートカット（州のマップやクエストログを開くなど）を、自分で設定できます</li><li>PC版：メインメニューに戻らずにゲームを終えられます。Steamのトレーディングカードに対応しました</li></ul><h3 id="遊びやすさ-1" tabindex="-1">遊びやすさ <a class="header-anchor" href="#遊びやすさ-1" aria-label="Permalink to &quot;遊びやすさ&quot;">​</a></h3><ul><li>円形闘技場・競馬場のイベントを自動でくり返せます</li><li>交易ルート：商品の絞り込みが残るようになり、ルートの複製もできます。PC版ではCtrl+クリックで船に移れます</li><li>道路の種類を、道路の建設パネルから切り替えられます</li><li>畑や森を、ブラシのように塗って置けます</li></ul><h3 id="バランス調整-2" tabindex="-1">バランス調整 <a class="header-anchor" href="#バランス調整-2" aria-label="Permalink to &quot;バランス調整&quot;">​</a></h3><ul><li><strong>パン</strong>：消費量がおよそ50%増えました。そのかわり、満たしたときの人口ボーナスが+2から+3に増えました</li><li><strong>ラティウムの粉ひき所</strong>：生産時間が30秒から20秒になりました（ゲームのデータでは、維持費12・労働力4・小麦の貯蔵12・小麦粉の貯蔵9）</li><li>円形闘技場の強化を10段階に作り直しました。輝きレベルIVで、リベルトゥスの需要にパンが加わります（気づかないうちにパンの需要が急に増えるので注意）</li><li>モニュメントの効果が島全体に効くようになりました</li><li>大きな事件（火災・疫病など）で被害を受ける建物が、かなり増えました</li><li>外交の贈り物の価値が大きく下がりました</li><li>祭りの頻度が下がりました</li><li>ウルカヌスの強化が、金鉱・炭鉱・金選鉱・炭焼き師にも効くようになりました</li><li>マルスの強化が、炭鉱・炭焼き師にも効くようになりました</li></ul><h3 id="主な修正-1" tabindex="-1">主な修正 <a class="header-anchor" href="#主な修正-1" aria-label="Permalink to &quot;主な修正&quot;">​</a></h3><ul><li>途中でライバルを追加すると落ちることがあったのを修正</li><li>アルビオンで大きな事件を解決できないことがあったのを修正</li><li>農場と農園に、畑で働く人が出るようになりました</li><li>マルチプレイで、ほかの人が持っていないDLCをホストが有効にすると固まる・同期がずれる問題を修正</li><li>PC版：MODの構成が違う人どうしではマルチプレイができないようになりました</li></ul><p>公式パッチノート：<a href="https://www.anno-union.com/updates/anno-117-pax-romana-patch-2-0/" target="_blank" rel="noreferrer">Anno 117: Pax Romana - Patch 2.0（Anno Union）</a></p><h2 id="関連ガイド" tabindex="-1">関連ガイド <a class="header-anchor" href="#関連ガイド" aria-label="Permalink to &quot;関連ガイド&quot;">​</a></h2><ul><li><a href="/guide/dlc03-dawn-of-delta.html">DLC03・デルタの夜明け</a></li><li><a href="/guide/dlc02-hippodrome.html">DLC02・競馬場</a></li><li><a href="/guide/strategy.html">攻略ガイド一覧</a></li></ul>',41)])])}const g=a(r,[["render",o]]);export{p as __pageData,g as default};
